def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    # flood fill zeros from border; unreached zeros -> 2
    seen=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==0 and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and not seen[i][j]: out[i][j]=2
    # for each shape: top row gap -> beam leftwards on row above
    shapes=set(); 
    for i in range(h):
        for j in range(w):
            if g[i][j]==5: shapes.add((i,j))
    comps=[]; vis=set()
    for c in shapes:
        if c in vis: continue
        st=[c]; comp=[]
        while st:
            x=st.pop()
            if x in vis: continue
            vis.add(x); comp.append(x)
            for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                y=(x[0]+di,x[1]+dj)
                if y in shapes and y not in vis: st.append(y)
        comps.append(comp)
    for comp in comps:
        top=min(i for i,j in comp); lft=min(j for i,j in comp); rgt=max(j for i,j in comp)
        toprow=[j for i,j in comp if i==top]
        gaps=[j for j in range(lft,rgt+1) if (top,j) not in comp]
        if gaps and top>0:
            # largest gap = opening
            j0=max(gaps)  # opening right edge? demo gap col4, beam to col0..4
            r=top-1
            j=j0
            while j>=0 and out[r][j]!=5:
                out[r][j]=2; j-=1
    return out
